def code(*args):

    num = args[0]
    digit = 0

    while (num > 0):
        last_digit = num % 10
        if (last_digit == 4 or last_digit == 7):
            digit += 1            
        num //= 10

    if (digit == 4 or digit == 7):
        return "YES"

    return "NO"

def is_nearly_lucky(num):
    count = 0
    while num > 0:
        digit = num % 10
        if digit == 4 or digit == 7:
            count += 1
        num //= 10
    return is_lucky(count)

if __name__ == "__main__":
